//! Public framework (`android:`) resource names and well-known attribute symbols, so references
//! into android.jar resolve without loading the framework table.

use std::sync::OnceLock;

/// Generated by `tests/data/res/regen-framework.sh`.
const FRAMEWORK: &str = include_str!("framework.txt");

/// (id, type, name) of every public framework resource, sorted by id.
fn framework() -> &'static [(u32, &'static str, &'static str)] {
    static TABLE: OnceLock<Vec<(u32, &'static str, &'static str)>> = OnceLock::new();
    TABLE.get_or_init(|| {
        let mut table = Vec::with_capacity(3200);
        let (mut typ, mut id) = ("", 0u32);
        for line in FRAMEWORK.lines() {
            if let Some(group) = line.strip_prefix('=') {
                let (t, first) = group.split_once(' ').unwrap_or_default();
                typ = t;
                id = u32::from_str_radix(first, 16).unwrap_or(0);
                continue;
            }
            if !line.is_empty() {
                table.push((id, typ, line));
            }
            id = id.wrapping_add(1);
        }
        table.sort_unstable_by_key(|&(id, _, _)| id);
        table
    })
}

/// (type, name) of a public framework resource id.
pub(crate) fn framework_name(id: u32) -> Option<(&'static str, &'static str)> {
    let table = framework();
    let i = table.binary_search_by_key(&id, |&(i, _, _)| i).ok()?;
    table.get(i).map(|&(_, t, n)| (t, n))
}

/// Name (without `android:`) of a framework attribute id.
pub(crate) fn android_attr_name(id: u32) -> Option<&'static str> {
    framework_name(id).filter(|(t, _)| *t == "attr").map(|(_, n)| n)
}

