/// Symbolic form of an integer value of a well-known framework enum/flag attribute.
pub(crate) fn android_attr_symbol(attr: &str, value: u32) -> Option<String> {
    let (_, flags, syms) = ANDROID_SYMBOLS.iter().find(|(n, _, _)| *n == attr)?;
    symbolize(value, *flags, syms.iter().map(|&(v, n)| (v, n)))
}

/// Maps `value` to an enum symbol, or to `a|b` flag symbols that cover it exactly. Flags are
/// taken greedily in table order, so wider symbols should come first.
pub(crate) fn symbolize<'a>(
    value: u32,
    flags: bool,
    syms: impl Iterator<Item = (u32, &'a str)> + Clone,
) -> Option<String> {
    if let Some((_, n)) = syms.clone().find(|&(v, _)| v == value) {
        return Some(n.to_string());
    }
    if !flags || value == 0 {
        return None;
    }
    let mut rest = value;
    let mut parts = Vec::new();
    for (v, n) in syms {
        if v != 0 && v & rest == v {
            parts.push(n);
            rest &= !v;
        }
    }
    (rest == 0).then(|| parts.join("|"))
}
